import{_ as i,o as e,c as o,a5 as t}from"./chunks/framework.CcrBcQWS.js";const b=JSON.parse('{"title":"사용자 책임 면책 조항","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/safety/user-responsibility-disclaimer.md","filePath":"ko/manual/safety/user-responsibility-disclaimer.md","lastUpdated":1787021357000}'),l={name:"ko/manual/safety/user-responsibility-disclaimer.md"};function r(s,a,n,h,d,u){return e(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="사용자-책임-면책-조항" tabindex="-1">사용자 책임 면책 조항 <a class="header-anchor" href="#사용자-책임-면책-조항" aria-label="Permalink to &quot;사용자 책임 면책 조항&quot;">​</a></h1><p>RBQ 및 관련 매뉴얼·소프트웨어를 사용할 때의 책임 범위와 제한 사항입니다.</p><div class="sb sb-required"><div class="sb-icon"><span class="sb-book" aria-hidden="true">📖</span></div><div class="sb-content"><p class="custom-block-title">필독 사항</p><p>사용 설명서 및 안전 관련 매뉴얼을 반드시 읽으세요. 법적·안전상 책임을 위해 해당 문서를 사전에 숙지해야 합니다.</p></div></div><h2 id="사용-용도와-금지-용도" tabindex="-1">사용 용도와 금지 용도 <a class="header-anchor" href="#사용-용도와-금지-용도" aria-label="Permalink to &quot;사용 용도와 금지 용도&quot;">​</a></h2><h3 id="의도된-사용" tabindex="-1">의도된 사용 <a class="header-anchor" href="#의도된-사용" aria-label="Permalink to &quot;의도된 사용&quot;">​</a></h3><ul><li>RBQ는 <strong>산업 현장, 제한 구역, 감독이 있는 환경</strong>에서 <strong>이동·운반</strong>을 목적으로 쓰는 4족 보행 로봇입니다.</li><li><strong>용도가 구분되거나 표시된 전용 구역</strong>에서 사용하는 것을 전제로 합니다. 이동·환경 한계는 <a href="/RBQ/nightly/ko/manual/safety/operating-environment-requirements.html">운영 환경 요구사항</a>과 <a href="/RBQ/nightly/ko/manual/hardware/specification.html">사양</a>을 참고하세요.</li><li>감지·모니터링 등 <strong>비접촉식 작업용 부착물</strong>을 실을 수 있으며, 해당 부착물에 전원을 공급할 수 있습니다.</li></ul><h3 id="적합하지-않은-사용" tabindex="-1">적합하지 않은 사용 <a class="header-anchor" href="#적합하지-않은-사용" aria-label="Permalink to &quot;적합하지 않은 사용&quot;">​</a></h3><ul><li>사람과 로봇이 <strong>같은 공간에서 계속 함께 작업하는 협업 용도</strong>에는 적합하지 않습니다.</li><li>위험 평가 없이 의도된 사용 범위를 벗어나 사용하는 것은 금지됩니다.</li></ul><h3 id="명시적-금지-사항" tabindex="-1">명시적 금지 사항 <a class="header-anchor" href="#명시적-금지-사항" aria-label="Permalink to &quot;명시적 금지 사항&quot;">​</a></h3><p>다음은 금지된 사용입니다. (예시이며 전부를 열거하지 않습니다.)</p><ul><li><strong>탑승 금지</strong>: 사람 또는 동물을 태우거나 운송하는 행위</li><li>수중·공중 사용, 무기·의료 기기 용도, 가정 환경 사용, 유해 물질 운반, 고의적 위해, 불법 목적, 등반 보조, 센서·환경 조작으로 기능 손상 등</li></ul><p><strong>저수준 API로 관절을 직접 제어하는 방식</strong>은 이 문서에서 말하는 의도된 사용 범위를 벗어납니다. 해당 방식으로 사용할 경우 <strong>별도 위험 평가</strong>가 필요합니다. <a href="/RBQ/nightly/ko/software/developers-guide.html">개발자 가이드</a> 및 API 문서를 참고하세요.</p><h2 id="적법-사용" tabindex="-1">적법 사용 <a class="header-anchor" href="#적법-사용" aria-label="Permalink to &quot;적법 사용&quot;">​</a></h2><ul><li>사용자는 적용되는 모든 법령·규정을 준수하여 제품을 사용할 책임이 있습니다.</li><li>제품은 매뉴얼과 Rainbow Robotics가 지정한 용도·환경·한도 내에서만 사용해야 합니다. 이를 위반한 사용으로 인한 손해에 대해서는 Rainbow Robotics가 책임지지 않습니다.</li></ul><h2 id="안전·리스크" tabindex="-1">안전·리스크 <a class="header-anchor" href="#안전·리스크" aria-label="Permalink to &quot;안전·리스크&quot;">​</a></h2><ul><li><strong>위험 평가</strong>: 실제 적용 환경(작업장, 사람·장비와의 공존 여부 등)에 대한 위험 평가를 사용자 또는 시스템 통합자가 수행해야 합니다. 안전 장치·가드·작업 절차는 그 결과에 맞게 구성하세요.</li><li><strong>교육</strong>: 조작·점검·유지보수에 관여하는 사람은 해당 매뉴얼과 안전 교육을 이수한 뒤 사용하세요.</li></ul><h2 id="개조·무단-수리" tabindex="-1">개조·무단 수리 <a class="header-anchor" href="#개조·무단-수리" aria-label="Permalink to &quot;개조·무단 수리&quot;">​</a></h2><ul><li>Rainbow Robotics의 승인 없이 제품을 개조하거나, 규정되지 않은 부품·소프트웨어로 변경한 경우, Rainbow Robotics는 그로 인한 고장·사고·손해에 대해 책임지지 않습니다.</li><li>수리·점검은 매뉴얼에 따라 사용자가 할 수 있는 범위 내에서 하거나, Rainbow Robotics에 문의하세요. <a href="/RBQ/nightly/ko/manual/troubleshooting/error-reporting.html">문의하기</a> 페이지를 참고하세요.</li></ul><h2 id="부적절한-사용" tabindex="-1">부적절한 사용 <a class="header-anchor" href="#부적절한-사용" aria-label="Permalink to &quot;부적절한 사용&quot;">​</a></h2><ul><li>부적절한 사용(폭발 위험 환경, 의료·생명 관련 용도, 인명·동물 수송, 위험 평가 없음, 사양 초과 사용 등)은 금지됩니다. 해당 사용으로 인한 직접·간접 손해에 대해서는 Rainbow Robotics가 책임지지 않습니다.</li></ul><p>제품 사용과 관련해 법적·안전상 문의가 있으면 Rainbow Robotics에 문의하세요. <a href="/RBQ/nightly/ko/manual/troubleshooting/error-reporting.html">문의하기</a> 페이지를 참고하세요.</p>',21)])])}const m=i(l,[["render",r]]);export{b as __pageData,m as default};
